"""Asserts the Python port equals fixtures generated by running the real TypeScript packages.

Only the parts that still have a TypeScript twin are checked: normalization, synthetic packs and
unit keys. The real Arabic packs and the dictionary are checked in the app that ships them.
Scheduling, persistence and reporting moved to FSRS in engine 0.6.0, and the TypeScript engine is
deprecated, so those are tested on their own in `tests/core/`.
"""

import hashlib
import json
import math
from collections import OrderedDict
from pathlib import Path

import pytest

import luraty_engine as L
from luraty_engine import _js
from luraty_engine.normalize import apply_step, apply_steps
from support.convert import to_js

PARITY = Path(__file__).parent / "parity"


def load(name):
    return json.loads((PARITY / f"{name}.json").read_text(encoding="utf-8"))


def dec(v):
    if isinstance(v, dict) and set(v) == {"$"}:
        return {
            "undefined": None,
            "NaN": math.nan,
            "Infinity": math.inf,
            "-Infinity": -math.inf,
            "-0": -0.0,
        }[v["$"]]
    return v





def must(result):
    assert result.ok, result
    return result.value


def assert_all(mismatches, total):
    assert total > 0, "vacuous parity check"
    assert not mismatches, f"{len(mismatches)}/{total} mismatches; first: {mismatches[:5]}"


def attempt(fn):
    try:
        value = fn()
    except TypeError:
        return {"throws": "TypeError"}
    return {"value": to_js(value)}


# ── normalize ───────────────────────────────────────────────────────────────────────────────────


def test_every_step_on_every_code_point():
    vectors = load("normalize")
    mismatches = []
    for step in vectors["steps"]:
        table = {int(k): v for k, v in vectors["changed"][step].items()}
        for c in range(0x110000):
            s = chr(c)
            if apply_step(step, s) != table.get(c, s):
                mismatches.append((step, hex(c)))
    assert_all(mismatches, 0x110000 * len(vectors["steps"]))


def test_every_step_on_adversarial_and_real_strings():
    vectors = load("normalize")
    mismatches = []
    total = 0
    for step, outputs in vectors["outputs"].items():
        for s, expected in zip(vectors["strings"], outputs, strict=True):
            total += 1
            if apply_step(step, s) != expected:
                mismatches.append((step, s, expected))
    for s, expected in zip(vectors["strings"], vectors["chained"], strict=True):
        total += 1
        if apply_steps(vectors["chain"], s) != expected:
            mismatches.append(("chain", s, expected))
    assert_all(mismatches, total)


def test_final_sigma_context_for_every_code_point():
    h = hashlib.sha256()
    lower = _js.to_lower_case
    for c in range(0x110000):
        if 0xD800 <= c <= 0xDFFF:
            continue
        x = chr(c)
        h.update(
            f"{lower(f'AΣ{x}')}|{lower(f'{x}Σ')}|{lower(f'A{x}Σ')}|{lower(f'AΣ{x}B')}\n".encode()
        )
    assert h.hexdigest() == load("normalize")["sigmaDigest"]


def test_whitespace_definitions():
    vectors = load("whitespace")
    identity = must(
        L.create_pack(
            {"id": "x", "tokenize": {"strategy": "regex", "pattern": "[a]+"}, "normalize": [], "compare": []},
            {"frequency": ""},
        )
    )
    split = []
    trim = []
    for c in range(0x10000):
        ch = chr(c)
        if len(L.vocabulary_of(identity, f"a{ch}b")) == 2:
            split.append(c)
        if ch != "a" and identity.compare(f"{ch}a{ch}", "a") == 1:
            trim.append(c)
    assert split == vectors["split"]
    assert trim == vectors["trim"]


# ── packs ───────────────────────────────────────────────────────────────────────────────────────








def test_create_pack():
    v = load("create_pack")
    mismatches = []
    for case, expected in zip(v["cases"], v["results"], strict=True):
        data = case["data"]
        if isinstance(data, dict) and "lemmasMap" in data:
            data = {"frequency": data["frequency"], "lemmas": OrderedDict(data["lemmasMap"])}
        try:
            r = L.create_pack(case["config"], data)
        except TypeError:
            if expected != {"throws": "TypeError"}:
                mismatches.append(("threw", case["config"]))
            continue
        if "throws" in expected:
            mismatches.append(("should throw", case["config"]))
            continue
        if not r.ok:
            if {"error": to_js(r.error)} != expected:
                mismatches.append((to_js(r.error), expected, case["config"]))
            continue
        p = r.value
        got = {
            "id": p.id,
            "keys": [attempt(lambda: p.key(s)) for s in v["probes"]],
            "candidates": [attempt(lambda: p.candidates(s)) for s in v["probes"]],
            "ranks": [attempt(lambda: p.rank(s)) for s in v["probes"]],
            "splits": [attempt(lambda: p.split(t)) for t in v["probeText"]],
            "compares": [attempt(lambda: p.compare(s, "a")) for s in v["probes"][:80]],
        }
        if got != expected:
            field = next((k for k in got if got[k] != expected.get(k)), None)
            if field in ("id", None):
                mismatches.append(("result", case["config"], field))
            else:
                diff = next(
                    (i, a, b) for i, (a, b) in enumerate(zip(got[field], expected[field], strict=True)) if a != b
                )
                mismatches.append((case["config"], field, diff, v["probes"][diff[0]] if field != "splits" else None))
    assert_all(mismatches, len(v["cases"]))


def test_check_pack():
    v = load("check_pack")
    session = load("session")
    built = {
        "fr": session["packs"]["fr"],
        "ar": session["packs"]["arf"],
        "de": session["packs"]["de"],
    }

    def cfg(over):
        return {
            "id": "p",
            "tokenize": {"strategy": "regex", "pattern": "[a-z]+"},
            "normalize": ["lowercase"],
            "compare": ["lowercase"],
            **over,
        }

    built.update(
        {
            "empty": [cfg({}), {"frequency": ""}],
            "ok": [cfg({}), {"frequency": "haus baum tuer"}],
            "unstable": [cfg({}), {"frequency": "haus baum", "lemmas": {"haus": "baum", "baum": "tuer"}}],
            "multi": [cfg({}), {"frequency": "haus baum", "lemmas": {"haus": ["haus", "baum"], "baum": "baum"}}],
            "driftReading": [
                cfg({}),
                {"frequency": "haus baum tuer", "lemmas": {"haus": ["haus", "baum"], "baum": "tuer"}},
            ],
            "compareEmpty": [cfg({"compare": ["lowercase", "stripPunctuation"]}), {"frequency": "haus"}],
        }
    )
    packs = {name: must(L.create_pack(c, d)) for name, (c, d) in built.items()}
    mismatches = []
    for case in v["results"]:
        got = to_js(L.check_pack(packs[case["pack"]], L.PackSample(text=case["sample"])))
        if got != case["problems"]:
            mismatches.append((case, got))

    def scripted(s):
        return L.LanguagePack(
            id=s["id"],
            split=lambda _: s["tokens"],
            key=lambda w: s["keys"].get(w, w),
            candidates=lambda w: s["candidates"].get(w, [s["keys"].get(w, w)]),
            rank=lambda w: s["ranks"].get(w),
            compare=lambda a, b: s["compare"][0] if a == b else s["compare"][1],
        )

    for s, expected in zip(v["scripted"], v["scriptedResults"], strict=True):
        got = to_js(L.check_pack(scripted(s), L.PackSample(text="x")))
        if got != expected:
            mismatches.append((s, got))
    assert_all(mismatches, len(v["results"]) + len(v["scripted"]))


# ── identifiers ────────────────────────────────────────────────────────────────────





def test_ids_and_constants():
    v = load("ids")
    c = v["constants"]
    assert to_js(L.COVERAGE_BAND) == c["COVERAGE_BAND"]
    assert list(L.DIRECTIONS) == c["DIRECTIONS"]
    assert list(L.MODALITIES) == c["MODALITIES"]
    assert L.SKILL == c["SKILL"]
    for u in v["units"]:
        s = u["s"]
        assert to_js(L.parse_unit_key(s)) == u["parse"], s
        assert L.is_unit_key(s) == u["isUnit"], s
        assert to_js(L.parse_skill_key(s)) == u["parseSkill"], s
        assert L.is_skill(s) == u["isSkill"], s
        assert L.is_modality(s) == u["isModality"], s
        assert L.variety(s) == u["variety"], s
    for m in v["mint"]:
        assert L.unit_key(m["m"], m["v"], m["w"]) == m["key"]
    for m in v["skills"]:
        assert L.skill_key(m["v"], m["w"]) == m["key"]



# ── session-level behaviour ─────────────────────────────────────────────────────────────────────


@pytest.fixture(scope="module")
def session():
    return load("session")



@pytest.fixture(scope="module")
def packs(session):
    out = {k: must(L.create_pack(*v)) for k, v in session["packs"].items()}
    return out





def test_bulk(session, packs):
    # Bulks over the real Arabic packs are checked in the app that ships those packs.
    bulks = [c for c in session["bulks"] if c["pack"] in packs]
    mismatches = []
    for c in bulks:
        fn = L.words_in if c["kind"] == "wordsIn" else L.vocabulary_of
        if list(fn(packs[c["pack"]], c["input"])) != c["r"]:
            mismatches.append(c)
    for c in session["lists"]:
        if to_js(L.keys_for(c["m"], "ar", c["words"])) != c["keys"]:
            mismatches.append(c)
    assert_all(mismatches, len(bulks) + len(session["lists"]))



